 84→// value is missing or malformed.  Explicit dose rate hints trump counts so the
 85→// selected reading reflects the most calibrated number available.
 86→func newMeasurementCandidate(key string, raw any) (measurementCandidate, bool) {
 87→	val, ok := numericValue(raw)
 88→	if !ok {
 89→		return measurementCandidate{}, false
 90→	}
 91→	lower := strings.ToLower(key)
 92→	candidate := measurementCandidate{
 93→		value:    val,
 94→		unit:     key,
 95→		key:      lower,
 96→		priority: priorityGenericCounts,
 97→	}
 98→	if strings.Contains(lower, "usv") {
 99→		candidate.unit = "µSv/h"
100→		candidate.priority = priorityDoseRate
101→		return candidate, true
102→	}
103→	if strings.Contains(lower, "urh") {
104→		candidate.value = val / 100.0
105→		candidate.unit = "µSv/h"
106→		candidate.priority = priorityDoseRate
107→		return candidate, true
108→	}
109→	if strings.Contains(lower, "cps") {
110→		candidate.priority = priorityCountsPerSecond
111→		return candidate, true
112→	}
113→	if strings.Contains(lower, "cpm") {
114→		candidate.priority = priorityCountsPerMinute
115→		return candidate, true
116→	}
