274→		}
275→		candidate, ok := newMeasurementCandidate(k, raw)
276→		if !ok {
277→			continue
278→		}
279→		if candidate.priority < best.priority || (candidate.priority == best.priority && candidate.key < best.key) {
280→			best = candidate
281→		}
282→	}
