291→			d.Time = t.Unix()
292→		}
293→	} else if v, ok := m["value_time"].(string); ok {
294→		if t, err := time.Parse(time.RFC3339, v); err == nil {
295→			d.Time = t.Unix()
296→		}
297→	} else if v, ok := m["captured_at"].(string); ok {
