326→// fetch pulls device data once.
327→// Returning raw payload keeps this function simple and lets callers derive
328→// both measurements and summaries without another pass.
329→func fetch(ctx context.Context, url string) ([]devicePayload, error) {
330→	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
331→	if err != nil {
332→		return nil, err
333→	}
334→	resp, err := http.DefaultClient.Do(req)
335→	if err != nil {
336→		return nil, err
337→	}
338→	defer resp.Body.Close()
339→	body, err := io.ReadAll(resp.Body)
340→	if err != nil {
341→		return nil, err
342→	}
343→	var raw []devicePayload
344→	if err := json.Unmarshal(body, &raw); err != nil {
345→		return nil, err
346→	}
347→	return raw, nil
348→}
