359→// cleanDetector strips IP-like tokens and normalises whitespace so the UI
360→// displays meaningful detector labels.  The helper follows "Clear is better
361→// than clever" by keeping the sanitising logic small and transparent.
362→func cleanDetector(raw string) string {
363→	trimmed := strings.TrimSpace(raw)
364→	if trimmed == "" {
365→		return ""
366→	}
367→	trimmed = strings.Trim(trimmed, "\"'")
368→	if trimmed == "" {
369→		return ""
370→	}
371→	if ip := net.ParseIP(trimmed); ip != nil {
372→		return ""
373→	}
374→	hasLetter := false
375→	for _, r := range trimmed {
376→		if unicode.IsLetter(r) {
377→			hasLetter = true
378→			break
379→		}
380→	}
381→	if !hasLetter {
382→		return ""
383→	}
384→	return strings.Join(strings.Fields(trimmed), " ")
385→}
