387→// DetectorLabel chooses the most descriptive string out of the available
388→// Safecast fields.  We prefer explicit tube information, then fall back to the
389→// transport hint, and finally the device name.  Returning a single string keeps
390→// the calling code tidy and avoids leaking implementation details elsewhere.
391→func DetectorLabel(tube, transport, name string) string {
392→	candidates := []string{tube, transport, name}
393→	for _, c := range candidates {
